insert into _k1_trivia values ('dragon-ball', 'series', 'dragon-ball', 'The franchise is called ドラゴンボール in Japan, read Doragon Bōru, and Dragon Ball is how it is written in English.', 'fun', 'wikipedia', 'https://en.wikipedia.org/wiki/Dragon_Ball_(TV_series)', 'published'), ('dragon-ball', 'series', 'dragon-ball', 'Akira Toriyama created the franchise and wrote and drew the original manga on his own.', 'history', 'wikipedia', 'https://en.wikipedia.org/wiki/Dragon_Ball', 'published'), ('dragon-ball', 'series', 'dragon-ball', 'After a long gap, Dragon Ball Super returned to television in July 2015 and ran for 131 episodes.', 'history', 'wikipedia', 'https://en.wikipedia.org/wiki/Dragon_Ball_Super_(TV_series)', 'published'), ('dragon-ball', 'series', 'dragon-ball', 'Daima aired its 20 episodes between October 2024 and February 2025.', 'history', 'wikipedia', 'https://en.wikipedia.org/wiki/Dragon_Ball_Daima', 'published'), ('dragon-ball', 'series', 'dragon-ball', 'Toei Animation produced the anime television series of the franchise.', 'history', 'wikipedia', 'https://en.wikipedia.org/wiki/Dragon_Ball_Z', 'published'), ('dragon-ball', 'series', 'dragon-ball', 'The Dragon Ball Super manga is drawn by Toyotarou and runs in V Jump rather than in Weekly Shonen Jump.', 'history', 'wikipedia', 'https://en.wikipedia.org/wiki/Dragon_Ball_Super', 'published'), ('dragon-ball', 'series', 'dragon-ball', 'The story was inspired by the Chinese novel Journey to the West, with Hong Kong kung fu films mixed in.', 'fun', 'wikipedia', 'https://en.wikipedia.org/wiki/Dragon_Ball', 'published'), ('dragon-ball', 'character', 'goku', 'Goku''s Japanese name, Son Goku, is how the Monkey King Sun Wukong of Journey to the West is read in Japanese.', 'fun', 'wikipedia', 'https://en.wikipedia.org/wiki/Dragon_Ball', 'published'), ('dragon-ball', 'series', 'dragon-ball', 'Daima is the last new anime story that Akira Toriyama conceived, and he died shortly before it aired.', 'history', 'wikipedia', 'https://en.wikipedia.org/wiki/Dragon_Ball_Daima', 'published'), ('dragon-ball', 'series', 'dragon-ball', 'The Dragon Ball Super manga went on hiatus after Akira Toriyama died in March 2024.', 'history', 'wikipedia', 'https://en.wikipedia.org/wiki/Dragon_Ball_Super', 'published'), ('dragon-ball', 'character', 'frieza', 'The name Frieza is a pun on freezer, and his Ginyu Force henchmen are named after fridge items.', 'fun', 'wikipedia', 'https://en.wikipedia.org/wiki/List_of_Dragon_Ball_characters', 'published'), ('dragon-ball', 'series', 'dragon-ball', 'The film Dragon Ball Super: Broly, set mostly after the Universe Survival Saga, arrived in Japan on 14 December 2018.', 'history', 'wikipedia', 'https://en.wikipedia.org/wiki/Dragon_Ball_Super', 'published'), ('dragon-ball', 'series', 'dragon-ball', 'Super Hero is the second Dragon Ball Super film, and its Japanese release came on 11 June 2022.', 'history', 'wikipedia', 'https://en.wikipedia.org/wiki/Dragon_Ball_Super', 'published'), ('dragon-ball', 'series', 'dragon-ball', 'Dragon Ball Z Kai is a re-edited version of Dragon Ball Z that aired from 2009 to 2015.', 'history', 'wikipedia', 'https://en.wikipedia.org/wiki/Dragon_Ball_Z', 'published'), ('dragon-ball', 'character', 'goku', 'Goku is a main character of Dragon Ball.', 'members', 'wikipedia', 'https://en.wikipedia.org/wiki/List_of_Dragon_Ball_characters', 'published'), ('dragon-ball', 'character', 'bulma', 'Bulma is a main character of Dragon Ball.', 'members', 'wikipedia', 'https://en.wikipedia.org/wiki/List_of_Dragon_Ball_characters', 'published'), ('dragon-ball', 'character', 'master-roshi', 'Master Roshi is a supporting character of Dragon Ball.', 'members', 'wikipedia', 'https://en.wikipedia.org/wiki/List_of_Dragon_Ball_characters', 'published'), ('dragon-ball', 'character', 'yamcha', 'Yamcha is a supporting character of Dragon Ball.', 'members', 'wikipedia', 'https://en.wikipedia.org/wiki/List_of_Dragon_Ball_characters', 'published'), ('dragon-ball', 'charac