insert into _k1_trivia values ('frieren', 'character', 'lawine', 'Lawine is a supporting character of Frieren: Beyond Journey''s End.', 'members', 'wikipedia', 'https://en.wikipedia.org/wiki/List_of_Frieren_characters', 'published'), ('frieren', 'character', 'wirbel', 'Wirbel is a supporting character of Frieren: Beyond Journey''s End.', 'members', 'wikipedia', 'https://en.wikipedia.org/wiki/List_of_Frieren_characters', 'published'), ('frieren', 'character', 'revolte', 'Revolte is an antagonist of Frieren: Beyond Journey''s End.', 'members', 'wikipedia', 'https://en.wikipedia.org/wiki/List_of_Frieren_characters', 'published'), ('frieren', 'character', 'hero-of-the-south', 'Hero of the South is a character of Frieren: Beyond Journey''s End.', 'members', 'wikipedia', 'https://en.wikipedia.org/wiki/List_of_Frieren_characters', 'published'), ('frieren', 'character', 'macht', 'Macht is an antagonist of Frieren: Beyond Journey''s End.', 'members', 'wikipedia', 'https://en.wikipedia.org/wiki/List_of_Frieren_characters', 'published'), ('fullmetal-alchemist', 'series', 'fullmetal-alchemist', 'The Japanese title is 鋼の錬金術師, read Hagane no Renkinjutsushi, which can be rendered as Alchemist of Steel.', 'fun', 'wikipedia', 'https://en.wikipedia.org/wiki/Fullmetal_Alchemist', 'published'), ('fullmetal-alchemist', 'series', 'fullmetal-alchemist', 'Hiromu Arakawa wrote and drew the Fullmetal Alchemist manga all by herself.', 'history', 'wikipedia', 'https://en.wikipedia.org/wiki/Fullmetal_Alchemist', 'published'), ('fullmetal-alchemist', 'series', 'fullmetal-alchemist', 'Square Enix published the manga in its Monthly Shōnen Gangan magazine, from July 2001 until June 2010.', 'history', 'wikipedia', 'https://en.wikipedia.org/wiki/Fullmetal_Alchemist', 'published'), ('fullmetal-alchemist', 'series', 'fullmetal-alchemist', 'The finished story fills 27 collected volumes.', 'history', 'wikipedia', 'https://en.wikipedia.org/wiki/Fullmetal_Alchemist', 'published'), ('fullmetal-alchemist', 'series', 'fullmetal-alchemist', 'Studio Bones produced the first TV anime. Its 51 episodes were broadcast on the MBS and TBS networks, starting in October 2003 and finishing a year later.', 'history', 'wikipedia', 'https://en.wikipedia.org/wiki/Fullmetal_Alchemist_(TV_series)', 'published'), ('fullmetal-alchemist', 'series', 'fullmetal-alchemist', 'Seiji Mizushima directed the 2003 anime, Shō Aikawa wrote it and Michiru Ōshima composed the score.', 'history', 'wikipedia', 'https://en.wikipedia.org/wiki/Fullmetal_Alchemist_(TV_series)', 'published'), ('fullmetal-alchemist', 'series', 'fullmetal-alchemist', 'Arakawa asked for an original ending, so the first anime left the manga plot after roughly a dozen episodes and told its own story.', 'history', 'wikipedia', 'https://en.wikipedia.org/wiki/Fullmetal_Alchemist_(TV_series)', 'published'), ('fullmetal-alchemist', 'series', 'fullmetal-alchemist', 'The second anime, Brotherhood, was shown on MBS and TBS from spring 2009 to summer 2010 and adapts the whole manga story in 64 episodes.', 'history', 'wikipedia', 'https://en.wikipedia.org/wiki/Fullmetal_Alchemist:_Brotherhood', 'published'), ('fullmetal-alchemist', 'series', 'fullmetal-alchemist', 'Yasuhiro Irie directed Brotherhood, Hiroshi Ōnogi wrote it and Akira Senju composed the music, all at Bones.', 'history', 'wikipedia', 'https://en.wikipedia.org/wiki/Fullmetal_Alchemist:_Brotherhood', 'published'), ('fullmetal-alchemist', 'series', 'fullmetal-alchemist', 'Two directors shaped the anime: Seiji Mizushima for the 2003 series and Yasuhiro Irie for Brotherhood.', 'history', 'wikipedia', 'https://en.wikipedia.org/wiki/Fullmetal_Alchemist:_Brotherhood', 'published'), ('fullmetal-alchemist', 'series', 'fullmetal-alchemist', 'The 2003 anime used four opening and four ending songs, swapping them roughly every dozen episodes.', 'music', 'wikipedia', 'https://en.wikipedia.org/wiki/List_of_Fullmetal_Alchemist_episodes', 'published'), ('fullmetal-alchemist', 'series', 'fullmetal-alchemist', 'Brotherhood went through five openings and five endings, and Sid sang both the first ending and the last opening.', 'music', 'wikipedia', 'https://en.wikipedia.org/wiki/List_of_Fullmetal_Alchemist:_Brotherhood_episodes', 'published'), ('fullmetal-alchemist', 'series', 'fullmetal-alchemist', 'The story comes in two anime adaptations of 51 and 64 episodes, 115 episodes between them, and questions name which one they mean.', 'history', 'wikipedia', 'https://en.wikipedia.org/wiki/Fullmetal_Alchemist_(TV_series)', 'published'), ('fullmetal-alchemist', 'character', 'dante', 'Dante exists only in the 2003 anime, where she is the main villain and an old flame of Hohenheim.', 'history', 'wikipedia', 'https://en.wikipedia.org/wiki/List_of_Fullmetal_Alchemist_characters', 'published'), ('fullmetal-alchemist', 'series', 'fullmetal-alchemist', 'The song Brothers, sung in Russian, became the 2003 anime''s signature piece and was never reused in Brotherhood.', 'music', 'wikipedia', 'https://en.wikipedia.org/wiki/Fullmetal_Alchemist_(TV_series)', 'published'), ('fullmetal-alchemist', 'character', 'lin-yao', 'The prince of Xing is Lin Yao in the Japanese manga, but the 2009 anime and Viz''s earliest English volumes write his name as Ling Yao.', 'fun', 'wikipedia', 'https://en.wikipedia.org/wiki/List_of_Fullmetal_Alchemist_characters', 'published'), ('fullmetal-alchemist', 'character', 'edward-elric', 'Edward Elric is a main character of Fullmetal Alchemist.', 'members', 'wikipedia', 'https://en.wikipedia.org/wiki/List_of_Fullmetal_Alchemist_characters', 'published'), ('fullmetal-alchemist', 'character', 'alphonse-elric', 'Alphonse Elric is a main character of Fullmetal Alchemist.', 'members', 'wikipedia', 'https://en.wikipedia.org/wiki/List_of_Fullmetal_Alchemist_characters', 'published'), ('fullmetal-alchemist', 'character', 'roy-mustang', 'Roy Mustang is a supporting character of Fullmetal Alchemist.', 'members', 'wikipedia', 'https://en.wikipedia.org/wiki/List_of_