insert into _k1_trivia values ('one-piece', 'character', 'charlotte-linlin', 'Charlotte Linlin is an antagonist of One Piece.', 'members', 'wikidata', 'https://www.wikidata.org/wiki/Q25399069', 'published'), ('one-piece', 'character', 'kaido', 'Kaido is an antagonist of One Piece.', 'members', 'wikidata', 'https://www.wikidata.org/wiki/Q22933371', 'published'), ('one-piece', 'character', 'yamato', 'Yamato is a supporting character of One Piece.', 'members', 'wikipedia', 'https://en.wikipedia.org/wiki/List_of_One_Piece_characters', 'published'), ('one-punch-man', 'series', 'one-punch-man', 'The title is written ワンパンマン in Japanese and read Wanpanman; English editions call it One-Punch Man.', 'fun', 'wikipedia', 'https://en.wikipedia.org/wiki/One-Punch_Man', 'published'), ('one-punch-man', 'series', 'one-punch-man', 'One came up with the story, and Yusuke Murata redrew it for the published manga.', 'history', 'wikipedia', 'https://en.wikipedia.org/wiki/One-Punch_Man', 'published'), ('one-punch-man', 'series', 'one-punch-man', 'The story began in 2009 as a webcomic that One put online himself, before any publisher was involved.', 'history', 'wikipedia', 'https://en.wikipedia.org/wiki/One-Punch_Man', 'published'), ('one-punch-man', 'series', 'one-punch-man', 'Murata''s redrawn version has appeared on Shueisha''s Tonari no Young Jump site since 14 June 2012.', 'history', 'wikipedia', 'https://en.wikipedia.org/wiki/One-Punch_Man', 'published'), ('one-punch-man', 'series', 'one-punch-man', 'Season 1 was animated by Madhouse under director Shingo Natsume and ran for 12 episodes from 5 October to 21 December 2015.', 'history', 'wikipedia', 'https://en.wikipedia.org/wiki/One-Punch_Man_season_1', 'published'), ('one-punch-man', 'series', 'one-punch-man', 'Season 2 moved to J.C.Staff with Chikara Sakurai directing; its 12 episodes, numbered 13 to 24 overall, aired from 10 April to 3 July 2019.', 'history', 'wikipedia', 'https://en.wikipedia.org/wiki/One-Punch_Man_season_2', 'published'), ('one-punch-man', 'series', 'one-punch-man', 'Season 3 stayed at J.C.Staff under director Shinpei Nagai: its first cours is episodes 25 to 36 (36 in total so far), with a second cours due in January 2027 and the manga beyond season 3 still ahead.', 'history', 'wikipedia', 'https://en.wikipedia.org/wiki/One-Punch_Man_season_3', 'published'), ('one-punch-man', 'series', 'one-punch-man', 'The Japanese name riffs on the children''s hero Anpanman, with wanpan serving as shorthand for a single punch.', 'fun', 'wikipedia', 'https://en.wikipedia.org/wiki/One-Punch_Man', 'published'), ('one-punch-man', 'series', 'one-punch-man', 'Season 1 opens with a JAM Project song and ends on Hiroko Moriguchi tracks, with a separate closing song for episode 12.', 'music', 'wikipedia', 'https://en.wikipedia.org/wiki/One-Punch_Man_season_1', 'published'), ('one-punch-man', 'series', 'one-punch-man', 'Season 2 pairs a JAM Project opening with a Makoto Furukawa ending; season 3 does the same, with Babymetal joining JAM Project.', 'music', 'wikipedia', 'https://en.wikipedia.org/wiki/One-Punch_Man', 'published'), ('one-punch-man', 'character', 'mumen-rider', 'His hero name jokes that he rides without a licence, and the character is a send-up of Kamen Rider.', 'fun', 'wikipedia', 'https://en.wikipedia.org/wiki/List_of_One-Punch_Man_characters', 'published'), ('one-punch-man', 'character', 'saitama', 'Saitama is a main character of One-Punch Man.', 'members', 'wikipedia', 'https://en.wikipedia.org/wiki/List_of_One-Punch_Man_characters', 'published'), ('one-punch-man', 'character', 'genos', 'Genos is a main character of One-Punch Man.', 'members', 'wikipedia', 'https://en.wikipedia.org/wiki/List_of_One-Punch_Man_characters', 'published'), ('one-punch-man', 'character', 'mumen-rider', 'Mumen Rider is a supporting character of One-Punch Man.', 'members', 'wikipedia', 'https://en.wikipedia.org/wiki/List_of_One-Punch_Man_characters', 'published'), ('one-punch-man', 'character', 'speed-o-sound-sonic', 'Speed-o''-Sound Sonic is an antagonist of One-Punch Man.', 'members', 'wikipedia', 'https://en.wikipedia.org/wiki/List_of_One-Punch_Man_characters', 'published'), ('one-punch-man', 'character', 'king', 'King is a supporting character of One-Punch Man.', 'members', 'wikipedia', 'https://en.wikipedia.org/wiki/List_of_One-Punch_Man_characters', 'published'), ('one-punch-man', 'character', 'bang', 'Bang is a supporting character of One-Punch Man.', 'members', 'wikipedia', 'https://en.wikipedia.org/wiki/List_of_One-Punch_Man_characters', 'published'), ('one-punch-man', 'character', 'atomic-samurai', 'Atomic Samurai is a supporting character of One-Punch Man.', 'members', 'wikipedia', 'https://en.wikipedia.org/wiki/List_of_One-Punch_Man_characters', 'published'), ('one-punch-man', 'character', 'tatsumaki', 'Tatsumaki is a supporting character of One-Punch Man.', 'members', 'wikipedia', 'https://en.wikipedia.org/wiki/List_of_One-Punch_Man_characters', 'published'), ('one-punch-man', 'character', 'garou', 'Garou is an antagonist of One-Punch Man.', 'members', 'wikipedia', 'https://en.wikipedia.org/wiki/List_of_One-Punch_Man_characters', 'published'), ('one-punch-man', 'character', 'boros', 'Boros is an antagonist of One-Punch Man.', 'members', 'wikipedia', 'https://en.wikipedia.org/wiki/List_of_One-Punch_Man_characters', 'published'), ('one-punch-man', 'character', 'fubuki', 'Fubuki is a supporting character of One-Punch Man.', 'members', 'wikipedia', 'https://en.wikipedia.org/wiki/List_of_One-Punch_Man_characters', 'published'), ('one-punch-man', 'character', 'blast', 'Blast is a character of One-Punch Man.', 'members', 'wikipedia', 'https://en.wikipedia.org/wiki/List_of_One-Punch_Man_characters', 'published'), ('oshi-no-ko', 'series', 'oshi-no-ko', 'The Japanese title is written 【推しの子】 inside corner brackets and read Oshi no Ko.', 'fun', 'wikipedia', 'https://en.wikipedia.org/wiki/Oshi_no_Ko', 'published'), ('oshi-no-ko', 'series', 'oshi-no-ko', 'Aka Akasaka wrote the story and Mengo Yokoyari drew the manga.', 'history', 'wikipedia', 'https://en.wikipedia.org/wiki/Oshi_no_Ko', 'published'), ('oshi-no-ko', 'series', 'oshi-no-ko', 'Shueisha''s Weekly Young Jump published the manga between April 2020 and November 2024.', 'history', 'wikipedia', 'https://en.wikipedia.org/wiki/Oshi_no_Ko', 'published'), ('oshi-no-ko', 'series', 'oshi-no-ko', 'The collected manga fills sixteen tankōbon volumes.', 'history', 'wikipedia', 'https://en.wikipedia.org/wiki/Oshi_no_Ko', 'published'), ('oshi-no-ko', 'series', 'oshi-no-ko', 'Doga Kobo animates the television series, with Daisuke Hiramaki directing, Jin Tanaka handling series composition and Takurō Iga composing.', 'history', 'wikipedia', 'https://en.wikipedia.org/wiki/Oshi_no_Ko_(TV_series)', 'published'), ('oshi-no-ko', 'series', 'oshi-no-ko', 'The first season ran eleven episodes, from April 12 to June 28, 2023.', 'history', 'wikipedia', 'https://en.wikipedia.org/wiki/List_of_Oshi_no_Ko_episodes', 'published'), ('oshi-no-ko', 'series', 'oshi-no-ko', 'The season opened with a feature-length first episode titled Mother and Children that also had a cinema screening on March 17, 2023.', 'fun', 'wikipedia', 'https://en.wikipedia.org/wiki/Oshi_no_Ko_(TV_series)', 'published'), ('oshi-no-ko', 'series', 'oshi-no-ko', 'The second season ran thirteen episodes, from July 3 to October 6, 2024.', 'history', 'wikipedia', 'https://en.wikipedia.org/wiki/List_of_Oshi_no_Ko_episodes', 'published'), ('oshi-no-ko', 'series', 'oshi-no-ko', 'Season one opens with Idol by YOASOBI and closes with Mephisto by Queen Bee.', 'music', 'wikipedia', 'https://en.wikipedia.org/wiki/Oshi_no_Ko_(TV_series)', 'published'), ('oshi-no-ko', 'series', 'oshi-no-ko', 'Season two uses Fatal by Gemn as its opening and Burning by Hitsujibungaku as its ending.', 'music', 'wikipedia', 'https://en.wikipedia.org/wiki/Oshi_no_Ko_(TV_series)', 'published'), ('oshi-no-ko', 'series', 'oshi-no-ko', 'Season three has Test Me by Chanmina as its opening and Serenade by Natori as its ending.', 'music', 'wikipedia', 'https://en.wikipedia.org/wiki/Oshi_no_Ko_(TV_series)', 'published'), ('oshi-no-ko', 'character', 'aqua-hoshino', 'The premise: the twins Aqua and Ruby are reborn, Aqua being the doctor Gorou Amamiya (雨宮 吾郎) and Ruby being his patient Sarina Tendōji (天童寺 さりな).', 'history', 'wikipedia', 'https://en.wikipedia.org/wiki/List_of_Oshi_no_Ko_characters', 'published'), ('oshi-no-ko', 'character', 'kana-arima', 'As a child, Kana Arima won fame as an acting prodigy who could produce tears whenever a scene needed them.', 'history', 'wikipedia', 'https://en.wikipedia.org/wiki/List_of_Oshi_no_Ko_characters', 'published'), ('oshi-no-ko', 'series', 'oshi-no-ko', 'A live-action series debuted on November 28, 2024, and a feature film titled The Final Act arrived on December 20, 2024.', 'history', 'wikipedia', 'https://en.wikipedia.org/wiki/Oshi_no_Ko', 'published'), ('oshi-no-ko', 'character', 'aqua-hoshino', 'Aqua Hoshino is a main character of Oshi no Ko.', 'members', 'wikipedia', 'https://en.wikipedia.org/wiki/List_of_Oshi_no_Ko_characters', 'published'), ('oshi-no-ko', 'character', 'ruby-hoshino', 'Ruby Hoshino is a main character of Oshi no Ko.', 'members', 'wikipedia', 'https://en.wikipedia.org/wiki/List_of_Oshi_no_Ko_characters', 'published'), ('oshi-no-ko', 'character', 'ai-hoshino', 'Ai Hoshino is a main character of Oshi no Ko.', 'members', 'wikipedia', 'https://en.wikipedia.org/wiki/List_of_Oshi_no_Ko_characters', 'published'), ('oshi-no-ko', 'character', 'kana-arima', 'Kana Arima is a main character of Oshi no Ko.', 'members', 'wikipedia', 'https://en.wikipedia.org/wiki/List_of_Oshi_no_Ko_characters', 'published'), ('oshi-no-ko', 'character', 'akane-kurokawa', 'Akane Kurokawa is a supporting character of Oshi no Ko.', 'members', 'wikipedia', 'https://en.wikipedia.org/wiki/List_of_Oshi_no_Ko_characters', 'published'), ('oshi-no-ko', 'character', 'mem-cho', 'MEM-cho is a supporting character of Oshi no Ko.', 'members', 'wikipedia', 'https://en.wikipedia.org/wiki/List_of_Oshi_no_Ko_characters', 'published'), ('oshi-no-ko', 'character', 'taishi-gotanda', 'Taishi Gotanda is a supporting character of Oshi no Ko.', 'members', 'wikipedia', 'https://en.wikipedia.org/wiki/List_of_Oshi_no_Ko_characters', 'published'), ('oshi-no-ko', 'character', 'ichigo-saito', 'Ichigo Saitō is a supporting character of Oshi no Ko.', 'members', 'wikipedia', 'https://en.wikipedia.org/wiki/List_of_Oshi_no_Ko_characters', 'published'), ('oshi-no-ko', 'character', 'miyako-saito', 'Miyako Saitō is a supporting character of Oshi no Ko.', 'members', 'wikipedia', 'https://en.wikipedia.org/wiki/List_of_Oshi_no_Ko_characters', 'published'), ('oshi-no-ko', 'character', 'melt-narushima', 'Melt Narushima is a supporting character of Oshi no Ko.', 'members', 'wikipedia', 'https://en.wikipedia.org/wiki/List_of_Oshi_no_Ko_characters', 'published'), ('oshi-no-ko', 'character', 'frill-shiranui', 'Frill Shiranui is a supporting character of Oshi no Ko.', 'members', 'wikipedia', 'https://en.wikipedia.org/wiki/List_of_Oshi_no_Ko_characters', 'published'), ('oshi-no-ko', 'character', 'taiki-himekawa', 'Taiki Himekawa is a supporting character of Oshi no Ko.', 'members', 'wikipedia', 'https://en.wikipedia.org/wiki/List_of_Oshi_no_Ko_characters', 'published'), ('oshi-no-ko', 'character', 'masaya-kaburagi', 'Masaya Kaburagi is a supporting character of Oshi no Ko.', 'members', 'wikipedia', 'https://en.wikipedia.org/wiki/List_of_Oshi_no_Ko_characters', 'published'), ('oshi-no-ko', 'character', 'pieyon', 'Pieyon is a supporting character of Oshi no Ko.', 'members', 'wikipedia', 'https://en.wikipedia.org/wiki/List_of_Oshi_no_Ko_characters', 'published'), ('oshi-no-ko', 'character', 'abiko-samejima', 'Abiko Samejima is a supporting character of Oshi no Ko.', 'members', 'wikipedia', 'https://en.wikipedia.org/wiki/List_of_Oshi_no_Ko_characters', 'published'), ('oshi-no-ko', 'character', 'yoriko-kichijouji', 'Yoriko Kichijouji is a supporting character of Oshi no Ko.', 'members', 'wikipedia', 'https://en.wikipedia.org/wiki/List_of_Oshi_no_Ko_characters', 'published'), ('oshi-no-ko', 'character', 'sakuya-kamoshida', 'Sakuya Kamoshida is a supporting character of Oshi no Ko.', 'members', 'wikipedia', 'https://en.wikipedia.org/wiki/List_of_Oshi_no_Ko_characters', 'published'), ('oshi-no-ko', 'character', 'minami-kotobuki', 'Minami Kotobuki is a supporting character of Oshi no Ko.', 'members', 'wikipedia', 'https://en.wikipedia.org/wiki/List_of_Oshi_no_Ko_characters', 'published'), ('sailor-moon', 'series', 'sailor-moon', 'In Japanese the title is 美少女戦士セーラームーン, read Bishōjo Senshi Sērā Mūn; it was first rendered in English as Pretty Soldier Sailor Moon and later as Pretty Guardian Sailor Moon.', 'fun', 'wikipedia', 'https://en.wikipedia.org/wiki/Sailor_Moon', 'published'), ('sailor-moon', 'series', 'sailor-moon', 'Naoko Takeuchi both wrote and drew the Sailor Moon manga.', 'history', 'wikipedia', 'https://en.wikipedia.org/wiki/Sailor_Moon', 'published'), ('sailor-moon', 'series', 'sailor-moon', 'Kodansha''s girls'' magazine Nakayoshi ran the manga from the end of December 1991 until early February 1997.', 'history', 'wikipedia', 'https://en.wikipedia.org/wiki/Sailor_Moon', 'published'), ('sailor-moon', 'series', 'sailor-moon', 'The manga won the 1993 Kodansha Manga Award in the shōjo category.', 'achievements', 'wikipedia', 'https://en.wikipedia.org/wiki/Sailor_Moon', 'published'), ('sailor-moon', 'series', 'sailor-moon', 'Toei Animation''s 1992 anime aired on TV Asahi from 7 March 1992 to 8 February 1997 and totals 200 episodes across 5 seasons.', 'history', 'wikipedia', 'https://en.wikipedia.org/wiki/Sailor_Moon_(TV_series)', 'published'), ('sailor-moon', 'series', 'sailor-moon', 'The manga''s five story arcs match the anime''s five seasons: 46, 43, 38, 39 and 34 episodes in 1992 anime order.', 'history', 'wikipedia', 'https://en.wikipedia.org/wiki/Sailor_Moon', 'published'), ('sailor-moon', 'series', 'sailor-moon', 'Junichi Sato directed the first season, Kunihiko Ikuhara the next three, and Takuya Igarashi the last.', 'history', 'wikipedia', 'https://en.wikipedia.org/wiki/Sailor_Moon_(TV_series)', 'published'), ('sailor-moon', 'series', 'sailor-moon', 'Sailor Moon Crystal, Toei''s reboot, has 39 episodes in three seasons; the third adapts the manga''s Infinity arc.', 'history', 'wikipedia', 'https://en.wikipedia.org/wiki/Sailor_Moon_Crystal', 'published'), ('sailor-moon', 'series', 'sailor-moon', 'The Crystal story continues in two-part films: Eternal in 2021 covers the Dream arc and Cosmos in 2023 covers the Stars arc.', 'history', 'wikipedia', 'https://en.wikipedia.org/wiki/Sailor_Moon_Crystal', 'published'), ('sailor-moon', 'series', 'sailor-moon', 'One opening, Moonlight Densetsu, served the first 166 episodes: DALI sang it for the first two seasons and Moon Lips for the next two.', 'music', 'wikipedia', 'https://en.wikipedia.org/wiki/Sailor_Moon_(TV_series)', 'published'), ('sailor-moon', 'series', 'sailor-moon', 'The last season has its own opening, Sailor Star Song by Kae Hanazawa, and the finale closes on Moon Lips'' Moonlight Densetsu.', 'music', 'wikipedia', 'https://en.wikipedia.org/wiki/Sailor_Moon_(TV_series)', 'published'), ('sailor-moon', 'character', 'usagi-tsukino', 'Usagi Tsukino is a main character of Sailor Moon.', 'members', 'wikipedia', 'https://en.wikipedia.org/wiki/List_of_Sailor_Moon_characters', 'published'), ('sailor-moon', 'character', 'ami-mizuno', 'Ami Mizuno is a supporting character of Sailor Moon.', 'members', 'wikipedia', 'https://en.wikipedia.org/wiki/List_of_Sailor_Moon_characters', 'published'), ('sailor-moon', 'character', 'rei-hino', 'Rei Hino is a supporting character of Sailor Moon.', 'members', 'wikipedia', 'https://en.wikipedia.org/wiki/List_of_Sailor_Moon_characters', 'published'), ('sailor-moon', 'character', 'makoto-kino', 'Makoto Kino is a supporting character of Sailor Moon.', 'members', 'wikipedia', 'https://en.wikipedia.org/wiki/List_of_Sailor_Moon_characters', 'published'), ('sailor-moon', 'character', 'minako-aino', 'Minako Aino is a supporting character of Sailor Moon.', 'members', 'wikipedia', 'https://en.wikipedia.org/wiki/List_of_Sailor_Moon_characters', 'published'), ('sailor-moon', 'character', 'mamoru-chiba', 'Mamoru Chiba is a supporting character of Sailor Moon.', 'members', 'wikipedia', 'https://en.wikipedia.org/wiki/List_of_Sailor_Moon_characters', 'published'), ('sailor-moon', 'character', 'luna', 'Luna is a supporting character of Sailor Moon.', 'members', 'wikipedia', 'https://en.wikipedia.org/wiki/List_of_Sailor_Moon_characters', 'published'), ('sailor-moon', 'character', 'artemis', 'Artemis is a supporting character of Sailor Moon.', 'members', 'wikipedia', 'https://en.wikipedia.org/wiki/List_of_Sailor_Moon_characters', 'published'), ('sailor-moon', 'character', 'queen-beryl', 'Queen Beryl is an antagonist of Sailor Moon.', 'members', 'wikipedia', 'https://en.wikipedia.org/wiki/List_of_Sailor_Moon_characters', 'published'), ('sailor-moon', 'character', 'chibiusa', 'Chibiusa is a supporting character of Sailor Moon.', 'members', 'wikipedia', 'https://en.wikipedia.org/wiki/List_of_Sailor_Moon_characters', 'published'), ('sailor-moon', 'character', 'haruka-tenoh', 'Haruka Tenoh is a supporting character of Sailor Moon.', 'members', 'wikipedia', 'https://en.wikipedia.org/wiki/List_of_Sailor_Moon_characters', 'published'), ('sailor-moon', 'character', 'michiru-kaioh', 'Michiru Kaioh is a supporting character of Sailor Moon.', 'members', 'wikipedia', 'https://en.wikipedia.org/wiki/List_of_Sailor_Moon_characters', 'published'), ('solo-leveling', 'series', 'solo-leveling', 'In Korea the story is titled 나 혼자만 레벨업, a phrase that English fans also translate as Only I Level Up.', 'fun', 'wikipedia', 'https://en.wikipedia.org/wiki/Solo_Leveling', 'published'), ('solo-leveling', 'series', 'solo-leveling', 'Written in Revised Romanization, the Korean name of Solo Leveling reads Na Honjaman Rebereop.', 'fun', 'wikipedia', 'https://en.wikipedia.org/wiki/Solo_Leveling', 'published'), ('solo-leveling', 'series', 'solo-leveling', 'The story began as a web novel by Chugong, first posted on the KakaoPage platform on 25 July 2016.', 'history', 'wikipedia', 'https://en.wikipedia.org/wiki/Solo_Leveling', 'published'), ('solo-leveling', 'series', 'solo-leveling', 'In print, the novel comes from the publisher D&C Media, under its Papyrus label, starting 4 November 2016.', 'history', 'wikipedia', 'https://en.wikipedia.org/wiki/Solo_Leveling', 'published'), ('solo-leveling', 'series', 'solo-leveling', 'The comic was split in two: the first season wrapped up on 19 March 2020, and a second one followed from August 2020 until December 2021.', 'history', 'wikipedia', 'https://en.wikipedia.org/wiki/Solo_Leveling', 'published'), ('solo-leveling', 'series', 'solo-leveling', 'The anime was animated by A-1 Pictures.', 'history', 'wikipedia', 'https://en.wikipedia.org/wiki/Solo_Leveling', 'published'), ('solo-leveling', 'series', 'solo-leveling', 'Shunsuke Nakashige directed the anime, with Noboru Kimura on the scripts and Hiroyuki Sawano composing the music.', 'history', 'wikipedia', 'https://en.wikipedia.org/wiki/Solo_Leveling_season_1', 'published'), ('solo-leveling', 'series', 'solo-leveling', 'The film Beyond the System is announced, so the story after Season 2 is still read on the page rather than seen in the series.', 'history', 'wikipedia', 'https://en.wikipedia.org/wiki/Solo_Leveling', 'published'), ('solo-leveling', 'series', 'solo-leveling', 'Over its two seasons the anime counts 25 episodes in total.', 'history', 'wikipedia', 'https://en.wikipedia.org/wiki/Solo_Leveling', 'published'), ('solo-leveling', 'series', 'solo-leveling', 'Season 1 opens with Level by SawanoHiroyuki[nZk]: Tomorrow X Together and closes with Request by Krage.', 'music', 'wikipedia', 'https://en.wikipedia.org/wiki/Solo_Leveling_season_1', 'published'), ('solo-leveling', 'series', 'solo-leveling', 'Season 2 opens with Reawaker by LiSA (feat. Felix of Stray Kids) and closes with Un-Apex by TK from Ling Tosite Sigure.', 'music', 'wikipedia', 'https://en.wikipedia.org/wiki/Solo_Leveling_season_2', 'published'), ('solo-leveling', 'series', 'solo-leveling', 'A recap special named How to Get Stronger went out on 25 February 2024 and covered the first seven episodes.', 'history', 'wikipedia', 'https://en.wikipedia.org/wiki/Solo_Leveling_season_1', 'published'), ('solo-leveling', 'series', 'solo-leveling', 'A compilation film of Season 1, Solo Leveling: ReAwakening, was shown in Japan with the first two episodes of Season 2 in late 2024.', 'history', 'wikipedia', 'https://en.wikipedia.org/wiki/Solo_Leveling', 'published'), ('solo-leveling', 'series', 'solo-leveling', 'The anime took the top prize, Anime of the Year, at the 9th Crunchyroll Anime Awards in 2025.', 'achievements', 'wikipedia', 'https://en.wikipedia.org/wiki/Solo_Leveling', 'published'), ('solo-leveling', 'series', 'solo-leveling', 'Kakao revealed a follow-up webtoon, Solo Leveling: Ragnarok, in April 2023.', 'history', 'wikipedia', 'https://en.wikipedia.org/wiki/Solo_Leveling', 'published'), ('solo-leveling', 'series', 'solo-leveling', 'The anime adaptation was first announced at the Anime Expo convention in 2022.', 'history', 'wikipedia', 'https://en.wikipedia.org/wiki/Solo_Leveling', 'published'), ('solo-leveling', 'series', 'solo-leveling', 'The anime''s official site shows a banner announcing that a theatrical film, Beyond the System, is in production.', 'history', 'official', 'https://sololeveling-anime.net/', 'published'), ('solo-leveling', 'character', 'sung-jin-woo', 'Sung Jin-woo starts out as a notoriously weak E-Rank Hunter, picked by a game-like power called The System.', 'fun', 'wikipedia', 'https://en.wikipedia.org/wiki/Solo_Leveling', 'published'), ('solo-leveling', 'character', 'igris', 'Igris is given the title Blood-Red Commander and is a knight with outstanding sword skill.', 'fun', 'wikipedia', 'https://en.wikipedia.org/wiki/Solo_Leveling', 'published');
insert into _k1_trivia values ('solo-leveling', 'character', 'cha-hae-in', 'Cha Hae-in is an S-Rank Hunter whose strength lies in fighting with a sword.', 'fun', 'wikipedia', 'https://en.wikipedia.org/wiki/Solo_Leveling', 'published'), ('solo-leveling', 'character', 'thomas-andre', 'The American Hunter Thomas Andre is nicknamed Goliath and counts as the strongest in his country.', 'fun', 'wikipedia', 'https://en.wikipedia.org/wiki/Solo_Leveling', 'published'), ('solo-leveling', 'character', 'ashborn', 'Ashborn rules the dead as a king and holds the Monarch of Shadows title.', 'fun', 'wikipedia', 'https://en.wikipedia.org/wiki/Solo_Leveling', 'published'), ('solo-leveling', 'character', 'antares', 'Antares is the King of Dragons and is counted as the most powerful of all the Monarchs.', 'fun', 'wikipedia', 'https://en.wikipedia.org/wiki/Solo_Leveling', 'published'), ('solo-leveling', 'character', 'sung-jin-woo', 'Sung Jin-woo is a main character of Solo Leveling.', 'members', 'wikipedia', 'https://en.wikipedia.org/wiki/Solo_Leveling', 'published'), ('solo-leveling', 'character', 'sung-jin-ah', 'Sung Jin-ah is a supporting character of Solo Leveling.', 'members', 'wikipedia', 'https://en.wikipedia.org/wiki/Solo_Leveling', 'published'), ('solo-leveling', 'character', 'park-kyung-hye', 'Park Kyung-hye is a supporting character of Solo Leveling.', 'members', 'wikipedia', 'https://en.wikipedia.org/wiki/Solo_Leveling', 'published'), ('solo-leveling', 'character', 'yoo-jin-ho', 'Yoo Jin-ho is a supporting character of Solo Leveling.', 'members', 'wikipedia', 'https://en.wikipedia.org/wiki/Solo_Leveling', 'published'), ('solo-leveling', 'character', 'lee-joo-hee', 'Lee Joo-hee is a supporting character of Solo Leveling.', 'members', 'wikipedia', 'https://en.wikipedia.org/wiki/Solo_Leveling', 'published'), ('solo-leveling', 'character', 'song-chi-yul', 'Song Chi-yul is a supporting character of Solo Leveling.', 'members', 'wikipedia', 'https://en.wikipedia.org/wiki/Solo_Level