racter', 'rakan', 'Rakan is an antagonist of Solo Leveling.', 'members', 'wikipedia', 'https://en.wikipedia.org/wiki/Solo_Leveling', 'published'), ('solo-leveling', 'character', 'sillad', 'Sillad is an antagonist of Solo Leveling.', 'members', 'wikipedia', 'https://en.wikipedia.org/wiki/Solo_Leveling', 'published'), ('solo-leveling', 'character', 'querehsha', 'Querehsha is an antagonist of Solo Leveling.', 'members', 'wikipedia', 'https://en.wikipedia.org/wiki/Solo_Leveling', 'published'), ('spy-x-family', 'series', 'spy-x-family', 'In Japan the title is written スパイファミリー, a katakana spelling of the English words spy and family.', 'fun', 'wikipedia', 'https://ja.wikipedia.org/wiki/SPY%C3%97FAMILY', 'published'), ('spy-x-family', 'series', 'spy-x-family', 'Tatsuya Endo both writes and draws the Spy × Family manga.', 'history', 'wikipedia', 'https://en.wikipedia.org/wiki/Spy_%C3%97_Family', 'published'), ('spy-x-family', 'series', 'spy-x-family', 'By the spring of 2026 the chapters filled seventeen collected tankōbon volumes.', 'history', 'wikipedia', 'https://en.wikipedia.org/wiki/Spy_%C3%97_Family', 'published'), ('spy-x-family', 'series', 'spy-x-family', 'Two studios share the animation, Wit Studio and CloverWorks.', 'history', 'wikipedia', 'https://en.wikipedia.org/wiki/Spy_%C3%97_Family_(TV_series)', 'published'), ('spy-x-family', 'series', 'spy-x-family', 'Kazuhiro Furuhashi directed the early seasons, with Takahiro Harada credited on season 2 and Yukiko Imai on season 3.', 'history', 'wikipedia', 'https://en.wikipedia.org/wiki/Spy_%C3%97_Family_(TV_series)', 'published'), ('spy-x-family', 'series', 'spy-x-family', 'Three seasons of the TV anime, 50 episodes in total, aired on TV Tokyo between April 2022 and December 2025.', 'history', 'wikipedia', 'https://en.wikipedia.org/wiki/Spy_%C3%97_Family_(TV_series)', 'published'), ('spy-x-family', 'series', 'spy-x-family', 'Each cour of the anime has its own pair of songs, from Official Hige Dandism and Gen Hoshino in the first to Spitz and Lilas Ikuta in the third season.', 'music', 'wikipedia', 'https://en.wikipedia.org/wiki/Spy_%C3%97_Family_(TV_series)', 'published'), ('spy-x-family', 'series', 'spy-x-family', 'Circulation had climbed past forty-two million copies by April 2026, which puts the manga among the biggest sellers ever.', 'achievements', 'wikipedia', 'https://en.wikipedia.org/wiki/Spy_%C3%97_Family', 'published'), ('spy-x-family', 'character', 'anya-forger', 'Anya can read minds, a gift that lets her see through the secret jobs of both of her new parents.', 'fun', 'wikipedia', 'https://en.wikipedia.org/wiki/Spy_%C3%97_Family', 'published'), ('spy-x-family', 'character', 'yor-forger', 'Yor works at City Hall by day, but in her other line of work she goes by the Thorn Princess.', 'fun', 'wikipedia', 'https://en.wikipedia.org/wiki/List_of_Spy_%C3%97_Family_characters', 'published'), ('spy-x-family', 'character', 'bond-forger', 'Bond the family dog can see short glimpses of the future, which only Anya knows about.', 'fun', 'wikipedia', 'https://en.wikipedia.org/wiki/Spy_%C3%97_Family', 'published'), ('spy-x-family', 'series', 'spy-x-family', 'A theatrical film, Code: White, reached Japanese cinemas in December 2023.', 'history', 'wikipedia', 'https://en.wikipedia.org/wiki/Spy_%C3%97_Family', 'published'), ('spy-x-family', 'series', 'spy-x-family', 'The Tokyo Anime Award Festival named the series its Animation of the Year.', 'achievements', 'wikipedia', 'https://en.wikipedia.org/wiki/Spy_%C3%97_Family_(TV_series)', 'published'), ('spy-x-family', 'character', 'anya-forger', 'In a FinT survey of Generation Z in Japan, the line about Anya liking peanuts came out as the most trending phrase of 2022.', 'fun', 'wikipedia', 'https://en.wikipedia.org/wiki/Spy_%C3%97_Family_(TV_series)', 'published'), ('spy-x-family', 'series', 'spy-x-family', 'Takuya Eguchi, Atsumi Tanezaki and Saori Hayami voice the three Forgers in the Japanese cast.', 'members', 'wikipedia', 'https://en.wikipedia.org/wiki/Spy_%C3%97_Family_(TV_series)', 'published'), ('spy-x-family', 'series', 'spy-x-family', 'Loid''s mission is code-named Operation Strix, and Sylvia Sherwood is the handler who oversees it.', 'fun', 'wikipedia', 'https://en.wikipedia.org/wiki/List_of_Spy_%C3%97_Family_characters', 'published'), ('spy-x-family', 'character', 'loid-forger', 'Loid Forger is a main character of Spy × Family.', 'members', 'wikipedia', 'https://en.wikipedia.org/wiki/Spy_%C3%97_Family_(TV_series)', 'published'), ('spy-x-family', 'character', 'anya-forger', 'Anya Forger is a main character of Spy × Family.', 'members', 'wikipedia', 'https://en.wikipedia.org/wiki/Spy_%C3%97_Family_(TV_series)', 'published'), ('spy-x-family', 'character', 'yor-forger', 'Yor Forger is a main character of Spy × Family.', 'members', 'wikipedia', 'https://en.wikipedia.org/wiki/Spy_%C3%97_Family_(TV_series)', 'published'), ('spy-x-family', 'character', 'bond-forger', 'Bond Forger is a main character of Spy × Family.', 'members', 'wikipedia', 'https://en.wikipedia.org/wiki/Spy_%C3%97_Family_(TV_series)', 'published'), ('spy-x-family', 'character', 'franky-franklin', 'Franky Franklin is a supporting character of Spy × Family.', 'members', 'wikipedia', 'https://en.wikipedia.org/wiki/Spy_%C3%97_Family_(TV_series)', 'published'), ('spy-x-family', 'character', 'sylvia-sherwood', 'Sylvia Sherwood is a supporting character of Spy × Family.', 'members', 'wikipedia', 'https://en.wikipedia.org/wiki/Spy_%C3%97_Family_(TV_series)', 'published'), ('spy-x-family', 'character', 'henry-henderson', 'Henry Henderson is a supporting character of Spy × Family.', 'members', 'wikipedia', 'https://en.wikipedia.org/wiki/Spy_%C3%97_Family_(TV_series)', 'published'), ('spy-x-family', 'character', 'yuri-briar', 'Yuri Briar is a supporting character of Spy × Family.', 'members', 'wikipedia', 'https://en.wikipedia.org/wiki/Spy_%C3%97_Family_(TV_series)', 'published'), ('spy-x-family', 'character', 'damian-desmond', 'Damian Desmond is a supporting character of Spy × Family.', 'members', 'wikipedia', 'https://en.wikipedia.org/wiki/Spy_%C3%97_Family_(TV_series)', 'published'), ('spy-x-family', 'character', 'becky-blackbell', 'Becky Blackbell is a supporting character of Spy × Family.', 'members', 'wikipedia', 'https://en.wikipedia.org/wiki/Spy_%C3%97_Family_(TV_series)', 'published'), ('spy-x-family', 'character', 'fiona-frost', 'Fiona Frost is a supporting character of Spy × Family.', 'members', 'wikipedia', 'https://en.wikipedia.org/wiki/Spy_%C3%97_Family_(TV_series)', 'published'), ('spy-x-family', 'character', 'camilla', 'Camilla is a supporting character of Spy × Family.', 'members', 'wikipedia', 'https://en.wikipedia.org/wiki/Spy_%C3%97_Family_(TV_series)', 'published'), ('spy-x-family', 'character', 'millie', 'Millie is a supporting character of Spy × Family.', 'members', 'wikipedia', 'https://en.wikipedia.org/wiki/Spy_%C3%97_Family_(TV_series)', 'published'), ('spy-x-family', 'character', 'sharon', 'Sharon is a supporting character of Spy × Family.', 'members', 'wikipedia', 'https://en.wikipedia.org/wiki/Spy_%C3%97_Family_(TV_series)', 'published'), ('spy-x-family', 'character', 'emile-elman', 'Emile Elman is a supporting character of Spy × Family.', 'members', 'wikipedia', 'https://en.wikipedia.org/wiki/Spy_%C3%97_Family_(TV_series)', 'published'), ('spy-x-family', 'character', 'ewen-egeburg', 'Ewen Egeburg is a supporting character of Spy × Family.', 'members', 'wikipedia', 'https://en.wikipedia.org/wiki/Spy_%C3%97_Family_(TV_series)', 'published'), ('spy-x-family', 'character', 'donovan-desmond', 'Donovan Desmond is an antagonist of Spy × Family.', 'members', 'wikipedia', 'https://en.wikipedia.org/wiki/Spy_%C3%97_Family_(TV_series)', 'published'), ('spy-x-family', 'character', 'dominic', 'Dominic is a supporting character of Spy × Family.', 'members', 'wikipedia', 'https://en.wikipedia.org/wiki/Spy_%C3%97_Family_(TV_series)', 'published'), ('spy-x-family', 'character', 'melinda-desmond', 'Melinda Desmond is a supporting character of Spy × Family.', 'members', 'wikipedia', 'https://ja.wikipedia.org/wiki/SPY%C3%97FAMILY', 'published'), ('spy-x-family', 'character', 'martha-marriott', 'Martha Marriott is a supporting character of Spy × Family.', 'members', 'wikipedia', 'https://en.wikipedia.org/wiki/List_of_Spy_%C3%97_Family_characters', 'published'), ('tower-of-god', 'series', 'tower-of-god', 'In Korea the series is called 신의 탑, written Sin-ui Tap in Latin letters, and English readers know it as Tower of God.', 'fun', 'wikipedia', 'https://en.wikipedia.org/wiki/List_of_Tower_of_God_characters', 'published'), ('tower-of-god', 'series', 'tower-of-god', 'One creator, working under the pen name S.I.U., writes and draws the series; his real name is Lee Jong-hui.', 'history', 'wikipedia', 'https://en.wikipedia.org/wiki/Tower_of_God', 'published'), ('tower-of-god', 'series', 'tower-of-god', 'The webtoon began on the Naver Webtoon platform on June 30, 2010, and new chapters keep coming there.', 'history', 'wikipedia', 'https://en.wikipedia.org/wiki/Tower_of_God', 'published'), ('tower-of-god', 'series', 'tower-of-god', 'It was among the first webtoons to get an official English translation, released through Line Webtoon from July 2014.', 'history', 'wikipedia', 'https://en.wikipedia.org/wiki/Tower_of_God', 'published'), ('tower-of-god', 'series', 'tower-of-god', 'The anime adaptation was first revealed at Seoul Comic-Con in August 2019, and the show reached screens in April 2020.', 'history', 'wikipedia', 'https://en.wikipedia.org/wiki/Tower_of_God', 'published'), ('tower-of-god', 'series', 'tower-of-god', 'Season one, made by Telecom Animation Film and directed by Takashi Sano, ran for 13 episodes in Japan between April 2 and June 24, 2020.', 'history', 'wikipedia', 'https://en.wikipedia.org/wiki/Tower_of_God_season_1', 'published'), ('tower-of-god', 'series', 'tower-of-god', 'Season two came from The Answer Studio and aired in two back-to-back cours, adding 26 episodes between July 7 and December 29, 2024.', 'history', 'wikipedia', 'https://en.wikipedia.org/wiki/Tower_of_God_season_2', 'published'), ('tower-of-god', 'series', 'tower-of-god', 'Takashi Sano directed season one; Akira Suzuki directed season two under chief director Kazuyoshi Takeuchi; Kevin Penkin wrote the music for both.', 'history', 'wikipedia', 'https://en.wikipedia.org/wiki/Tower_of_God', 'published'), ('tower-of-god', 'series', 'tower-of-god', 'Stray Kids performed both songs that frame season one.', 'music', 'wikipedia', 'https://en.wikipedia.org/wiki/Tower_of_God_season_1', 'published'), ('tower-of-god', 'series', 'tower-of-god', 'Season two changed singers between its two cours: NiziU first, then Stray Kids again.', 'music', 'wikipedia', 'https://en.wikipedia.org/wiki/Tower_of_God_season_2', 'published'), ('tower-of-god', 'theme', 'op-1', 'Stray Kids sang the season one songs in Japanese, English and Korean, one version for each language dub.', 'music', 'wikipedia', 'https://en.wikipedia.org/wiki/Tower_of_God_season_1', 'published'), ('tower-of-god', 'series', 'tower-of-god', 'The anime so far covers season one plus the two cours of season two, 39 episodes in all, and the webtoon runs further.', 'history', 'wikipedia', 'https://en.wikipedia.org/wiki/Tower_of_God_season_2', 'published'), ('tower-of-god', 'series', 'tower-of-god', 'Shinsu, which means roughly Divine Water, is the substance that fills the Tower and gets stronger and denser on the higher floors.', 'fun', 'wikipedia', 'https://en.wikipedia.org/wiki/Tower_of_God', 'published'), ('tower-of-god', 'series', 'tower-of-god', 'Climbers chosen from outside are Regulars, those who reach the top are Rankers, and the rare people who open the Tower''s doors themselves are Irregulars.', 'fun', 'wikipedia', 'https://en.wikipedia.org/wiki/Tower_of_God', 'published'), ('tower-of-god', 'character', 'twenty-fifth-bam', 'Bam''s full Korean name translates literally as Twenty-fifth Night.', 'fun', 'wikipedia', 'https://en.wikipedia.org/wiki/List_of_Tower_of_God_characters', 'published'), ('tower-of-god', 'series', 'tower-of-god', 'The creator lines up major events and characters long before they appear, in some cases more than eight years ahead.', 'fun', 'wikipedia', 'https://en.wikipedia.org/wiki/Tower_of_God', 'published'), ('tower-of-god', 'character', 'twenty-fifth-bam', 'Twenty-Fifth Bam is a main character of Tower of God.', 'members', 'wikipedia', 'https://en.wikipedia.org/wiki/List_of_Tower_of_God_characters', 'published'), ('tower-of-god', 'character', 'rachel', 'Rachel is a main character of Tower of God.', 'members', 'wikipedia', 'https://en.wikipedia.org/wiki/List_of_Tower_of_God_characters', 'published'), ('tower-of-god', 'character', 'khun-aguero-agnes', 'Khun Aguero Agnes is a supporting character of Tower of God.', 'members', 'wikipedia', 'https://en.wikipedia.org/wiki/List_of_Tower_of_God_characters', 'published'), ('tower-of-god', 'character', 'rak-wraithraiser', 'Rak Wraithraiser is a supporting character of Tower of God.', 'members', 'wikipedia', 'https://en.wikipedia.org/wiki/List_of_Tower_of_God_characters', 'published'), ('tower-of-god', 'character', 'headon', 'Headon is a character of Tower of God.', 'members', 'wikipedia', 'https://en.wikipedia.org/wiki/List_of_Tower_of_God_characters', 'published'), ('tower-of-god', 'character', 'shibisu', 'Shibisu is a supporting character of Tower of God.', 'members', 'wikipedia', 'https://en.wikipedia.org/wiki/List_of_Tower_of_God_characters', 'published'), ('tower-of-god', 'character', 'hatz', 'Hatz is a supporting character of Tower of God.', 'members', 'wikipedia', 'https://en.wikipedia.org/wiki/List_of_Tower_of_God_characters', 'published'), ('tower-of-god', 'character', 'phonsekal-lauroe', 'Phonsekal Lauroe is a supporting character of Tower of God.', 'members', 'wikipedia', 'https://en.wikipedia.org/wiki/List_of_Tower_of_God_characters', 'published'), ('tower-of-god', 'character', 'anaak-jahad', 'Anaak Jahad is a supporting character of Tower of God.', 'members', 'wikipedia', 'https://en.wikipedia.org/wiki/List_of_Tower_of_God_characters', 'published'), ('tower-of-god', 'character', 'jahad', 'Jahad is an antagonist of Tower of God.', 'members', 'wikipedia', 'https://en.wikipedia.org/wiki/List_of_Tower_of_God_characters', 'published'), ('tower-of-god', 'character', 'endorsi-jahad', 'Endorsi Jahad is a supporting character of Tower of God.', 'members', 'wikipedia', 'https://en.wikipedia.org/wiki/List_of_Tower_of_God_characters', 'published'), ('tower-of-god', 'character', 'ha-yuri-jahad', 'Ha-Yuri Jahad is a supporting character of Tower of God.', 'members', 'wikipedia', 'https://en.wikipedia.org/wiki/List_of_Tower_of_God_characters', 'published'), ('tower-of-god', 'character', 'evan-edrok', 'Evan Edrok is a supporting character of Tower of God.', 'members', 'wikipedia', 'https://en.wikipedia.org/wiki/List_of_Tower_of_God_characters', 'published'), ('tower-of-god', 'character', 'ja-wangnan', 'Ja Wangnan is a main character of Tower of God.', 'members', 'wikipedia', 'https://en.wikipedia.org/wiki/List_of_Tower_of_God_characters', 'published');
insert into _k1_trivia values ('tower-of-god', 'character', 'hwa-ryun', 'Hwa Ryun is a supporting character of Tower of God.', 'members', 'wikipedia', 'https://en.wikipedia.org/wiki/List_of_Tower_of_God_characters', 'published'), ('tower-of-god', 'character', 'urek-mazino', 'Urek Mazino is a supporting character of Tower of God.', 'members', 'wikipedia', 'https://en.wikipedia.org/wiki/List_of_Tower_of_God_characters', 'published'), ('tower-of-god', 'character', 'ha-jinsung', 'Ha Jinsung is a supporting character of Tower of God.', 'members', 'wikipedia', 'https://en.wikipedia.org/wiki/List_of_Tower_of_God_characters', 'published'), ('tower-of-god', 'character', 'enryu', 'Enryu is a supporting character of Tower of God.', 'members', 'wikipedia', 'https://en.wikipedia.org/wiki/List_of_Tower_of_God_characters', 'published'), ('tower-of-god', 'character', 'white', 'White is an antagonist of Tower of God.', 'members', 'wikipedia', 'https://en.wikipedia.org/wiki/List_of_Tower_of_God_characters', 'published'), ('tower-of-god', 'character', 'phantaminum', 'Phantaminum is an antagonist of Tower of God.', 'members', 'wikipedia', 'https://en.wikipedia.org/wiki/List_of_Tower_of_God_characters', 'published'), ('vinland-saga', 'series', 'vinland-saga', 'Vinland Saga is written ヴィンランド・サガ in Japanese and read Vinrando Saga.', 'fun', 'wikipedia', 'https://en.wikipedia.org/wiki/Vinland_Saga_(manga)', 'published'), ('vinland-saga', 'series', 'vinland-saga', 'Makoto Yukimura writes and draws the manga, which Kodansha publishes; his name is 幸村誠 in Japanese.', 'history', 'wikipedia', 'https://en.wikipedia.org/wiki/Vinland_Saga_(manga)', 'published'), ('vinland-saga', 'series', 'vinland-saga', 'The manga began in Weekly Shōnen Magazine in April 2005, moved to Monthly Afternoon on December 24, 2005, and finished there on July 25, 2025.', 'history', 'wikipedia', 'https://en.wikipedia.org/wiki/Vinland_Saga_(manga)', 'published'), ('vinland-saga', 'series', 'vinland-saga', 'The story is collected in 29 volumes holding 220 chapters, and the last volume came out on September 22, 2025.', 'history', 'wikipedia', 'https://en.wikipedia.org/wiki/List_of_Vinland_Saga_chapters', 'published'), ('vinland-saga', 'series', 'vinland-saga', 'Wit Studio animated the first season under director Shūhei Yabuta; its 24 episodes were shown on NHK General TV from July 8 to December 30, 2019.', 'history', 'wikipedia', 'https://en.wikipedia.org/wiki/Vinland_Saga_(TV_series)', 'published'), ('vinland-saga', 'series', 'vinland-saga', 'MAPPA took over for the second season, which aired 24 more episodes, numbered 25 to 48 overall, from January 10 to June 20, 2023.', 'history', 'wikipedia', 'https://en.wikipedia.org/wiki/List_of_Vinland_Saga_episodes', 'published'), ('vinland-saga', 'series', 'vinland-saga', 'Season one opened with Mukanjyo by Survive Said the Prophet and later Dark Crow by Man with a Mission, and closed with Torches by Aimer and later Drown by milet.', 'music', 'wikipedia', 'https://en.wikipedia.org/wiki/Vinland_Saga_(TV_series)', 'published'), ('vinland-saga', 'series', 'vinland-saga', 'Season two used River by Anonymouz and then Paradox by Survive Said the Prophet as openings, with Without Love by LMYK and Ember by haju:harmonics as endings.', 'music', 'wikipedia', 'https://en.wikipedia.org/wiki/Vinland_Saga_(TV_series)', 'published'), ('vinland-saga', 'series', 'vinland-saga', 'The manga article divides the plot into four arcs: the War Arc, the Slave Arc, the Eastern Expedition Arc and the Vinland Arc.', 'history', 'wikipedia', 'https://en.wikipedia.org/wiki/Vinland_Saga_(manga)', 'published'), ('vinland-saga', 'series', 'vinland-saga', 'Using the numbered chapter list, the War Arc fills chapters 1 to 54 (season one) and the Slave Arc chapters 55 to 100 (season two); the last two arcs are not animated yet.', 'history', 'wikipedia', 'https://en.wikipedia.org/wiki/List_of_Vinland_Saga_chapters', 'published'), ('vinland-saga', 'series', 'vinland-saga', 'In 2009 the Japan Media Arts Festival gave the manga its top honor, and Kodansha''s general-manga prize followed in 2012; circulation topped 7 million copies by August 2022.', 'achievements', 'wikipedia', 'https://en.wikipedia.org/wiki/Vinland_Saga_(manga)', 'published'), ('vinland-saga', 'series', 'vinland-saga', 'Kodansha USA publishes the manga in English in two-in-one hardcovers, starting on October 14, 2013.', 'history', 'wikipedia', 'https://en.wikipedia.org/wiki/Vinland_Saga_(manga)', 'published'), ('vinland-saga', 'character', 'thorfinn', 'The series dramatizes the expedition of the real Icelandic explorer Thorfinn Karlsefni, and the lead is a fictional counterpart of him.', 'fun', 'wikipedia', 'https://en.wikipedia.org/wiki/Vinland_Saga_(manga)', 'published'), ('vinland-saga', 'character', 'thors', 'Thors earned the epithet the Troll of Jom as a Jomsviking general, then quietly left war behind to live as a pacifist farmer.', 'fun', 'wikipedia', 'https://en.wikipedia.org/wiki/List_of_Vinland_Saga_characters', 'published'), ('vinland-saga', 'character', 'thorfinn', 'Thorfinn is a main character of Vinland Saga.', 'members', 'wikipedia', 'https://en.wikipedia.org/wiki/List_of_Vinland_Saga_characters', 'published'), ('vinland-saga', 'character', 'askeladd', 'Askeladd is a main character of Vinland Saga.', 'members', 'wikipedia', 'https://en.wikipedia.org/wiki/List_of_Vinland_Saga_characters', 'published'), ('vinland-saga', 'character', 'thors', 'Thors is a supporting character of Vinland Saga.', 'members', 'wikipedia', 'https://en.wikipedia.org/wiki/List_of_Vinland_Saga_characters', 'published'), ('vinland-saga', 'character', 'canute', 'Canute is a main character of Vinland Saga.', 'members', 'wikipedia', 'https://en.wikipedia.org/wiki/List_of_Vinland_Saga_characters', 'published'), ('vinland-saga', 'character', 'thorkell', 'Thorkell is a supporting character of Vinland Saga.', 'members', 'wikipedia', 'https://en.wikipedia.org/wiki/List_of_Vinland_Saga_characters', 'published'), ('vinland-saga', 'character', 'leif', 'Leif is a supporting character of Vinland Saga.', 'members', 'wikipedia', 'https://en.wikipedia.org/wiki/List_of_Vinland_Saga_characters', 'published'), ('vinland-saga', 'character', 'floki', 'Floki is an antagonist of Vinland Saga.', 'members', 'wikipedia', 'https://en.wikipedia.org/wiki/List_of_Vinland_Saga_characters', 'published'), ('vinland-saga', 'character', 'bjorn', 'Bjorn is a supporting character of Vinland Saga.', 'members', 'wikipedia', 'https://en.wikipedia.org/wiki/List_of_Vinland_Saga_characters', 'published'), ('vinland-saga', 'character', 'einar', 'Einar is a main character of Vinland Saga.', 'members', 'wikipedia', 'https://en.wikipedia.org/wiki/List_of_Vinland_Saga_characters', 'published'), ('vinland-saga', 'character', 'ketil', 'Ketil is a supporting character of Vinland Saga.', 'members', 'wikipedia', 'https://en.wikipedia.org/wiki/List_of_Vinland_Saga_characters', 'published'), ('vinland-saga', 'character', 'gudrid', 'Gudrid is a supporting character of Vinland Saga.', 'members', 'wikipedia', 'https://en.wikipedia.org/wiki/List_of_Vinland_Saga_characters', 'published'), ('vinland-saga', 'character', 'hild', 'Hild is a supporting character of Vinland Saga.', 'members', 'wikipedia', 'https://en.wikipedia.org/wiki/List_of_Vinland_Saga_characters', 'published');
insert into public.trivia (entity_kind, entity_id, group_id, fact, category, source, source_url, lang, status, site_id) select v.entity_kind, v.entity_id, g.id, v.fact, v.category, v.source, v.source_url, 'en', v.status, 'anime' from _k1_trivia v join public.groups g on g.slug = v.group_slug and g.site_id = 'anime' where not exists (select 1 from public.trivia t where t.entity_kind = v.entity_kind and t.entity_id = v.entity_id and md5(btrim(lower(t.fact))) = md5(btrim(lower(v.fact))));
