-- L05-K1-facts.sql (run O1, lane L1; generated by apps/quiz/e2e/o1/L1/content-sql.mjs, do not edit by hand)
--
-- What:   1348 entity_sources rows and 1032 trivia rows (1032 published because the owner verified them, the rest draft). A draft row of an earlier run whose fact is verified now is promoted; nothing is ever demoted.
-- Needs:  L04.
-- Verify: select count(*) from public.trivia where site_id = 'anime';   expect 1032
-- Undo:   L05-K1-facts.rollback.sql.
-- o1-transaction: single (psql --single-transaction). Idempotent: a second run changes nothing.

set lock_timeout = '5s';
set client_min_messages = warning;
do $o1l$ begin
  if (select count(*) from public.groups where site_id = 'anime' and slug in ('apothecary-diaries', 'attack-on-titan', 'bleach', 'blue-lock', 'chainsaw-man', 'cowboy-bebop', 'dandadan', 'death-note', 'demon-slayer', 'dragon-ball', 'evangelion', 'frieren', 'fullmetal-alchemist', 'haikyu', 'hunter-x-hunter', 'jojo', 'jujutsu-kaisen', 'kagurabachi', 'kaiju-no-8', 'my-hero-academia', 'naruto', 'omniscient-readers-viewpoint', 'one-piece', 'one-punch-man', 'oshi-no-ko', 'sailor-moon', 'solo-leveling', 'spy-x-family', 'tower-of-god', 'vinland-saga', 'anime-mix')) <> 31 then
    raise exception 'L05: the series groups are missing (apply L04 first)';
  end if;
end $o1l$;

do $o1l$ begin
  if not exists (select 1 from information_schema.columns where table_schema = 'public' and table_name = 'trivia' and column_name = 'site_id') or not exists (select 1 from information_schema.columns where table_schema = 'public' and table_name = 'entity_sources' and column_name = 'source_url') then
    raise exception 'L05: trivia.site_id or entity_sources.source_url is missing (apply 002a and 011 first)';
  end if;
end $o1l$;





































































































































































































































































































































































































































































































































































































































































































































































































































































































































































































































































































































































































































































































































































































create temp table _k1_trivia (group_slug text, entity_kind text, entity_id text, fact text, category text, source text, source_url text, status text) on commit drop;












update public.trivia t set category = v.category, source = v.source, source_url = v.source_url, updated_at = now() from _k1_trivia v where t.site_id = 'anime' and t.entity_kind = v.entity_kind and t.entity_id = v.entity_id and md5(btrim(lower(t.fact))) = md5(btrim(lower(v.fact))) and (t.category, t.source, t.source_url) is distinct from (v.category, v.source, v.source_url);

update public.trivia t set status = v.status, updated_at = now() from _k1_trivia v where t.site_id = 'anime' and t.entity_kind = v.entity_kind and t.entity_id = v.entity_id and md5(btrim(lower(t.fact))) = md5(btrim(lower(v.fact))) and t.status = 'draft' and v.status in ('published', 'hidden');


delete from public.trivia t where t.site_id = 'anime' and t.status = 'draft' and t.created_by is null and t.group_id in (select id from public.groups where site_id = 'anime' and slug in ('apothecary-diaries', 'attack-on-titan', 'bleach', 'blue-lock', 'chainsaw-man', 'cowboy-bebop', 'dandadan', 'death-note', 'demon-slayer', 'dragon-ball', 'evangelion', 'frieren', 'fullmetal-alchemist', 'haikyu', 'hunter-x-hunter', 'jojo', 'jujutsu-kaisen', 'kagurabachi', 'kaiju-no-8', 'my-hero-academia', 'naruto', 'omniscient-readers-viewpoint', 'one-piece', 'one-punch-man', 'oshi-no-ko', 'sailor-moon', 'solo-leveling', 'spy-x-family', 'tower-of-god', 'vinland-saga')) and not exists (select 1 from _k1_trivia v where t.entity_kind = v.entity_kind and t.entity_id = v.entity_id and md5(btrim(lower(t.fact))) = md5(btrim(lower(v.fact))));

update public.trivia t set status = 'published', updated_at = now() from _k1_trivia v where t.site_id = 'anime' and t.entity_kind = v.entity_kind and t.entity_id = v.entity_id and md5(btrim(lower(t.fact))) = md5(btrim(lower(v.fact))) and v.status = 'published' and t.status = 'draft' and t.created_by is null;
